import { isBytesValue } from '../bencode/bytes-value.mjs';
import { isDictValue } from '../bencode/dict-value.mjs';

function chooseQuote(text) {
  if (text.includes("'") && !text.includes('"')) {
    return '"';
  }

  return "'";
}

function escapeBytesText(text, quote) {
  let escaped = '';

  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    const code = text.charCodeAt(index);

    if (character === '\\') {
      escaped += '\\\\';
      continue;
    }

    if (character === quote) {
      escaped += `\\${quote}`;
      continue;
    }

    if (code === 9) {
      escaped += '\\t';
      continue;
    }

    if (code === 10) {
      escaped += '\\n';
      continue;
    }

    if (code === 13) {
      escaped += '\\r';
      continue;
    }

    if (code >= 32 && code <= 126) {
      escaped += character;
      continue;
    }

    escaped += `\\x${code.toString(16).padStart(2, '0')}`;
  }

  return escaped;
}

function formatBytesValue(value) {
  const quote = chooseQuote(value.text);
  return `b${quote}${escapeBytesText(value.text, quote)}${quote}`;
}

export function formatPythonValue(value) {
  if (typeof value === 'number') {
    return String(value);
  }

  if (isBytesValue(value)) {
    return formatBytesValue(value);
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => formatPythonValue(item)).join(', ')}]`;
  }

  if (isDictValue(value)) {
    return `{${value.entries.map(([key, item]) => `${formatPythonValue(key)}: ${formatPythonValue(item)}`).join(', ')}}`;
  }

  return String(value);
}

