import { formatHelp, formatUsage } from './messages.mjs';
import { getProgramName } from './program-name.mjs';

export class CliExit extends Error {
  constructor(exitCode, stdout = '', stderr = '') {
    super(stderr || stdout);
    this.name = 'CliExit';
    this.exitCode = exitCode;
    this.stdout = stdout;
    this.stderr = stderr;
  }
}

function isNegativeNumberToken(token) {
  return /^-\d/.test(token);
}

function isOptionLikeToken(token) {
  return token.startsWith('-') && token !== '-' && !isNegativeNumberToken(token);
}

export function parseArgs(argv = process.argv) {
  const programName = getProgramName(argv);
  const tokens = argv.slice(2);
  const unknownTokens = [];
  let helpRequested = false;
  let hasA = false;
  let aValue = '';

  for (let index = 0; index < tokens.length; index += 1) {
    const token = tokens[index];

    if (token === '--a') {
      const next = tokens[index + 1];

      if (next === undefined || isOptionLikeToken(next)) {
        throw new CliExit(
          2,
          '',
          `${formatUsage(programName)}\n${programName}: error: argument --a: expected one argument\n`,
        );
      }

      hasA = true;
      aValue = next;
      index += 1;
      continue;
    }

    if (token.startsWith('--a=')) {
      hasA = true;
      aValue = token.slice(4);
      continue;
    }

    if (token === '-h' || token === '--help') {
      helpRequested = true;
      continue;
    }

    unknownTokens.push(token);
  }

  if (helpRequested) {
    throw new CliExit(0, `${formatHelp(programName)}\n`, '');
  }

  if (!hasA) {
    throw new CliExit(
      2,
      '',
      `${formatUsage(programName)}\n${programName}: error: the following arguments are required: --a\n`,
    );
  }

  if (unknownTokens.length > 0) {
    throw new CliExit(
      2,
      '',
      `${formatUsage(programName)}\n${programName}: error: unrecognized arguments: ${unknownTokens.join(' ')}\n`,
    );
  }

  return { a: aValue };
}

